    return int(value)


def _coerce_float(value: str) -> float:
    return float(value)


def _coerce_bool(value: str) -> bool:
    lower = value.lower()
    if lower in ("true", "yes", "1"):
        return True
    if lower in ("false", "no", "0"):
        return False
    raise EnvCfgError(f"Cannot coerce '{value}' to bool")


def _coerce_str(value: str) -> str:
    return value


def _coerce(value: str, expected: type) -> Any:
    if expected is int:
