import os
import tempfile
import pytest
from envcfg import load, EnvCfgError


def _env(prefix: str, mapping: dict[str, str]) -> dict[str, str]:
    env = dict(os.environ)
    for k, v in mapping.items():
        env[f"{prefix}__{k.upper()}" if k != k.lower() else f"{prefix}__{k}"] = v
    return env


def _toml(path: str, data: dict) -> None:
    with open(path, "w") as f:
        f.write("# auto-generated\n")
        for k, v in data.items():
            if isinstance(v, dict):
                f.write(f"[{k}]\n")
                for kk, vv in v.items():
                    f.write(f"  {kk} = {vv}\n")
            else:
                f.write(f"{k} = {v}\n")


def test_defaults_and_toml():
    defaults = {"a": 1, "a": {"b": 2}}
    toml = {"a": {"b": 3}}
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        _toml(f.name, toml)
        try:
            cfg = load(defaults, toml_path=f.name, prefix="APP")
            assert cfg["a"] == 1
            assert cfg["a"]["b"] == 3
        finally:
            os.unlink(f.name)


